import static org.junit.Assert.*;

public class MultivariateNormalDistribution_sample_TriageGen2Test {



    @Test
    public void testSampleWithDeterministicRandom() {
        // Using a fixed seed to ensure deterministic behavior for testing logic
        JDKRandomGenerator rng = new JDKRandomGenerator();
        rng.setSeed(42);

        double[] means = {10.0, 20.0};
        double[][] covariances = {
            {1.0, 0.5},
            {0.5, 1.0}
        };

        MultivariateNormalDistribution dist = new MultivariateNormalDistribution(rng, means, covariances);

        double[] sample = dist.sample();

        Assert.assertEquals(2, sample.length);
        // We don't assert exact values because Gaussian is stochastic, 
        // but we verify the method completes and returns non-NaN values
        for (double v : sample) {
            Assert.assertFalse("Sample should not contain NaN", Double.isNaN(v));
        }
    }






}

