import org.apache.commons.math3.util.MathArrays;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

public class MultivariateNormalDistribution_sample_TriageGen2Test {





    @Test
    public void testSampleStatisticalProperties() {
        // Large sample size to verify mean property via Law of Large Numbers
        double[] means = {5.0, -2.0};
        double[][] covariances = {
            {1.0, 0.0},
            {0.0, 1.0}
        };
        MultivariateNormalDistribution dist = new MultivariateNormalDistribution(means, covariances);

        int iterations = 10000;
        double sum0 = 0;
        double sum1 = 0;

        for (int i = 0; i < iterations; i++) {
            double[] s = dist.sample();
            sum0 += s[0];
            sum1 += s[1];
        }

        double avg0 = sum0 / iterations;
        double avg1 = sum1 / iterations;

        // Tolerance for statistical convergence
        Assert.assertEquals("Mean of first dimension should converge to 5.0", 5.0, avg0, 0.1);
        Assert.assertEquals("Mean of second dimension should converge to -2.0", -2.0, avg1, 0.1);
    }




}

