import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

public class MultivariateNormalDistribution_sample_TriageGen2Test {









    @Test
    public void testCorrelationEffect() {
        // Test with high correlation to ensure samplingMatrix.operate(normalVals) works
        double[] means = {0.0, 0.0};
        double rho = 0.99;
        double[][] covariances = {
            {1.0, rho},
            {rho, 1.0}
        };
        MultivariateNormalDistribution dist = new MultivariateNormalDistribution(means, covariances);

        int iterations = 1000;
        int countHighCorrelation = 0;

        for (int i = 0; i < iterations; i++) {
            double[] s = dist.sample();
            // If rho is high, s[0] and s[1] should likely have the same sign
            if ((s[0] > 0 && s[1] > 0) || (s[0] < 0 && s[1] < 0)) {
                countHighCorrelation++;
            }
        }

        // For rho=0.99, the sign should match much more than 50% of the time
        Assert.assertTrue("Samples should show high correlation", countHighCorrelation > 800);
    }
}
